anger_effects.RUS_change_popular_anger:
RUS_change_popular_anger = {
	if = {
		limit = {
			has_idea = RUS_popular_anger
			OR = {
				check_variable = { RUS_anger_change > 0 }
				AND = {
					check_variable = { RUS_anger_change < 0 }
					check_variable = { RUS_popular_anger > 0 }
				}
			}
		}

		# avoid going < 1 or > 10
		set_temp_variable = {
			RUS_anger_change = {
				value = RUS_anger_change
				clamp = { min = { value = 1 subtract = RUS_popular_anger } max = { value = 10 subtract = RUS_popular_anger } }
			}
		}

		if = {
			limit = {
				OR = {
					NOT = { has_variable = RUS_popular_anger } #bypass the check when initialising
					NOT = { check_variable = { RUS_anger_change = 0 } }
				}
			}
			if = {
				limit = { check_variable = { RUS_anger_change > 0 } }
				custom_effect_tooltip = RUS_increase_pop_anger
				log = "Popular Anger Increased"
			}
			else = {
				custom_effect_tooltip = RUS_decrease_pop_anger
				log = "Popular Anger Decreased"
			}

			# set the new variables
			add_to_variable = { RUS_popular_anger = RUS_anger_change }
			add_to_variable = { RUS_popular_anger_pp = { value = 0.04 multiply = RUS_anger_change } }
			add_to_variable = { RUS_popular_anger_stability = { value = -0.02 multiply = RUS_anger_change } }
			add_to_variable = { RUS_popular_anger_factory_output = { value = -0.01 multiply = RUS_anger_change } }

			log = "Current anger levels: Military Anger = [?RUS_military_anger], Popular Anger = [?RUS_popular_anger], Right-Anger = [?RUS_right_anger], Left-Anger = [?RUS_left_anger]"
		}
		if = {
			limit = {
				check_variable = { RUS_popular_anger > 6 }
			}
			custom_effect_tooltip = RUS_popular_anger_7_tt
		}

		hidden_effect = {
			if = {
				limit = {
					has_war_with = GER
					surrender_progress > 0.25
					check_variable = { RUS_popular_anger > 9 }
				}
				country_event = { id = russia_events.918 days = 4 random_days = 4 }
			}
			else_if = {
				limit = {
					check_variable = { RUS_popular_anger > 9 }
				}
				country_event = { id = russia_events.924 days = 4 random_days = 4 }
			}
			else_if = {
				limit = {
					check_variable = { RUS_popular_anger > 8 }
				}
				country_event = { id = russia_events.923 days = 4 random_days = 4 }
			}
			else_if = {
				limit = {
					check_variable = { RUS_popular_anger > 7 }
				}
				country_event = { id = russia_events.922 days = 4 random_days = 4 }
			}
			else_if = {
				limit = {
					check_variable = { RUS_popular_anger > 6 }
				}
				country_event = { id = russia_events.921 days = 4 random_days = 4 }
			}
			else_if = {
				limit = {
					check_variable = { RUS_popular_anger > 5 }
				}
				country_event = { id = russia_events.920 days = 4 random_days = 4 }
			}
		}
	}
}

